arguments.new_text:
from ledger.report.json_output import render_json
from ledger.report.summary import summarize
from ledger.report.table import render_table


def cmd_report(args):
    entries = read_entries(args.file, since=args.since)
    summary = summarize(entries)
    if args.format == "json":
        return render_json(summary)
    return render_table(summary)

    assert render_table({"food": -2000}) == "food       -20.00\ntotal      -20.00"


def test_render_json():
    assert json.loads(render_json({"food": -2000})) == {"accounts": {"food": "-20.00"}, "total": "-20.00"}

